<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepName;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\LogoutToken;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\Gateway\TokenSigner;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\User\Domain\PublicLoginAuthResponse;
use Psr\Http\Message\ResponseInterface;

final class AuthenticationDomainExtraUnitTest extends TestCase
{
    // --- StepName enum ---

    public function test_step_name_values(): void
    {
        $this->assertSame('login', StepName::LOGIN->value);
        $this->assertSame('consent', StepName::CONSENT->value);
        $this->assertSame('mfa', StepName::MFA->value);
        $this->assertSame('webauthn-login', StepName::WEBAUTHN_LOGIN->value);
        $this->assertSame('magic-link', StepName::MAGIC_LINK->value);
    }

    public function test_step_name_from_value(): void
    {
        $this->assertSame(StepName::LOGIN, StepName::from('login'));
        $this->assertSame(StepName::MFA, StepName::from('mfa'));
    }

    // --- StepResult ---

    public function test_step_result_render(): void
    {
        $response = $this->createMock(ResponseInterface::class);
        $challenges = new ChallengesState();
        $result = StepResult::render($response, $challenges);

        $this->assertSame(StepResult::TYPE_RENDER, $result->type);
        $this->assertSame($response, $result->response);
        $this->assertNull($result->authResponse);
        $this->assertSame($challenges, $result->challenges);
    }

    public function test_step_result_proceed(): void
    {
        $auth = new AuthenticationResult(valid: true, id: 'u1', tenant: 't');
        $resp = new PublicLoginAuthResponse(
            tenant: 't',
            auth: $auth,
            issuer: 'https://iss',
            clientId: 'c',
            authExpiration: new DateInterval('PT1H'),
            idData: [],
            idExpiration: new DateInterval('PT1H'),
            sessionId: 's',
            sessionExpiration: new DateInterval('P1D'),
        );
        $challenges = new ChallengesState();
        $result = StepResult::proceed($resp, $challenges);

        $this->assertSame(StepResult::TYPE_PROCEED, $result->type);
        $this->assertNull($result->response);
        $this->assertSame($resp, $result->authResponse);
    }

    // --- LogoutToken ---

    public function test_logout_token_builds_with_correct_claims(): void
    {
        $capturedClaims = null;
        $signer = new class ($capturedClaims) implements TokenSigner {
            public ?array $claims = null;
            public function sign(string $t, array $d, \DateInterval $e): string
            {
                $this->claims = $d;
                return 'logout-jwt';
            }
            public function keysAsJwks(string $t): \Jose\Component\Core\JWKSet
            {
                return new \Jose\Component\Core\JWKSet([]);
            }
            public function signKeypass(string $t, array $d, \DateInterval $e): string
            {
                return '';
            }
            public function verifyTokenPayload(string $t, string $tok): ?array
            {
                return null;
            }
            public function verifiedKeypass(string $t, string $tok): mixed
            {
                return null;
            }
            public function parseSignedPayload(string $t, string $tok): ?array
            {
                return null;
            }
        };

        $token = LogoutToken::build($signer, 'tenant', 'https://iss', 'user-1', 'client-1', 'sess-1');

        $this->assertSame('logout-jwt', $token);
        $this->assertSame('logout+jwt', $signer->claims['typ']);
        $this->assertSame('https://iss', $signer->claims['iss']);
        $this->assertSame('user-1', $signer->claims['sub']);
        $this->assertSame('client-1', $signer->claims['aud']);
        $this->assertSame('sess-1', $signer->claims['sid']);
        $this->assertArrayHasKey('events', $signer->claims);
    }
}
